const hmacKey = 'pa4qacea4VK9t9nGv7yZtwmj';
const candidateAnswers = ['Smith', 'Fluffy', 'London', 'Blue'];
for (const ans of candidateAnswers) {
  const hash = crypto.createHmac('sha256', hmacKey).update(ans).digest('hex');
  console.log(`${ans}: ${hash}`);
